selectors.rule:
.call-dialog {
  display: flex; width: min(740px, 100%); max-height: min(650px, calc(100svh - 32px));
  flex-direction: column; overflow: hidden; border: 1px solid #e3e9e1; border-radius: 15px;
  background: var(--color-canvas); box-shadow: 0 20px 70px rgba(10, 26, 17, .32);
}

.space-discovery-dialog {
  display: flex;
  width: min(720px, calc(100vw - 30px));
  max-height: min(780px, calc(100dvh - 32px));
  min-width: 0;
  box-sizing: border-box;
  flex-direction: column;
  gap: 16px;
  overflow: hidden;
}

:root:is([data-theme], :not([data-theme])) .form-error,
:root:is([data-theme], :not([data-theme])) .list-error,
:root:is([data-theme], :not([data-theme])) .inline-error { color: var(--color-text-primary); border-color: var(--color-danger); background: var(--color-danger-soft); }
